import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=mid',{waitUntil:'domcontentloaded',timeout:25000}).catch(e=>console.log('goto',e.message))
await pg.waitForTimeout(2500)
const info = await pg.evaluate(()=>{
  const out={}
  const host=document.querySelector('.ref8443-range-host')
  const input=document.querySelector('input[type=range]')
  function desc(el){ if(!el)return null; const cs=getComputedStyle(el); return {tag:el.tagName, cls:el.className, border:cs.border, borderWidth:cs.borderWidth, outline:cs.outline, boxShadow:cs.boxShadow, bg:cs.background.slice(0,40), w:el.getBoundingClientRect().width, h:el.getBoundingClientRect().height} }
  out.input=desc(input)
  out.host=desc(host)
  // walk up parents checking for border/outline
  let chain=[]; let el=host
  for(let i=0;i<5&&el;i++){ chain.push(desc(el)); el=el.parentElement }
  out.parents=chain
  return out
})
console.log(JSON.stringify(info,null,2))
await pg.screenshot({path:'D:/repository/_range.png'})
await b.close()

